        artist_id = artist["id"]
        artist_names_from_songs[artist_id] = artist["name"]
        artist_recommended_song_ids.setdefault(artist_id, set()).add(song_id)
artist_recommendation_counts = {artist_id: len(song_ids) for artist_id, song_ids in artist_recommended_song_ids.items()}
minimum_recommendation_count = min(artist_recommendation_counts.values())
least_recommended_artist_ids = sorted(artist_id for artist_id, count in artist_recommendation_counts.items() if count == minimum_recommendation_count)
print({"minimum_recommended_song_count": minimum_recommendation_count, "least_recommended_candidates": [{"artist_id": artist_id, "name": artist_names_from_songs[artist_id], "recommended_song_count": artist_recommendation_counts[artist_id]} for artist_id in least_recommended_artist_ids]})
if len(least_recommended_artist_ids) != 1:
    raise RuntimeError("The public recommendation records do not determine a unique least-recommended artist.")
least_recommended_artist_id = least_recommended_artist_ids[0]
